public interface IInventoryReservation
{
    bool TryReserve(string sku, int quantity);
    void Release(string sku, int quantity);
    int Available(string sku);
}

public sealed class InventoryReservation : IInventoryReservation
{
    private readonly object _sync = new();
    private readonly Dictionary<string, int> _stock = new();
    private readonly Dictionary<string, int> _reserved = new();

    public InventoryReservation(IReadOnlyDictionary<string, int> initialStock)
    {
        foreach (var kv in initialStock)
            _stock[kv.Key] = kv.Value;
    }

    public bool TryReserve(string sku, int quantity)
    {
        if (quantity <= 0) return false;
        lock (_sync)
        {
            _stock.TryGetValue(sku, out var onHand);
            _reserved.TryGetValue(sku, out var held);
            if (onHand - held < quantity) return false;
            _reserved[sku] = held + quantity;
            return true;
        }
    }

    public void Release(string sku, int quantity)
    {
        lock (_sync)
        {
            _reserved.TryGetValue(sku, out var held);
            var next = Math.Max(0, held - quantity);
            if (next == 0) _reserved.Remove(sku);
            else _reserved[sku] = next;
        }
    }

    public int Available(string sku)
    {
        lock (_sync)
        {
            _stock.TryGetValue(sku, out var onHand);
            _reserved.TryGetValue(sku, out var held);
            return onHand - held;
        }
    }
}
